contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put on c with a chosen unlock time and amount. The test is payable
    // and must send Ether from this contract into c when invoking Put.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "not enough funds to forward");

        // Read observable before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Call Put and capture whether it reverted
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Put reverted then nothing observable must have changed; otherwise
        // the holder balance must have increased exactly by amount and contract balance too.
        assert(
            reverted
            ? (beforeBalance == afterBalance && contractBalBefore == contractBalAfter && beforeUnlock == afterUnlock)
            : (afterBalance == beforeBalance + amount && contractBalAfter == contractBalBefore + amount)
        );
    }

    // allow receiving Ether to fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first ensure there is a balance >= MinSum by calling Put with some amount,
    // then attempt Collect for an amount _am. The function is payable so it can fund Put.
    function run(uint unlockOffset, uint putAmount, uint _am) public payable {
        // ensure this contract can forward putAmount
        require(address(this).balance >= putAmount, "insufficient funds to Put");
        // normalize unlock time: pass a time in the future by adding offset to block.timestamp
        uint unlockTime = block.timestamp + unlockOffset;

        // Read before-values for this test contract's holder record and contract balance
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // First fund the account on c by calling Put (may revert)
        bool putReverted;
        try c.Put{value: putAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put, read values
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint contractBalMid = address(c).balance;

        // Now attempt Collect for amount _am (may revert). Ensure we only attempt Collect when _am is not absurdly large to avoid underflow in our assertion logic: but do not constraint relation to c state.
        bool collectReverted;
        try c.Collect(_am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // The general rule we assert:
        // - If Collect executed (did not revert) then midBalance >= _am and block.timestamp > midUnlock must have held (these preconditions in C's Collect),
        //   and as a result the stored balance decreases by exactly _am and address(c).balance decreases by exactly _am.
        // - If Collect reverted then neither the stored balance nor contract balance changed by Collect (they equal the mid-values).
        // Note: We express this by comparing mid vs after and contract balances. We also include that if Collect succeeded then afterBalance = midBalance - _am and contractBalAfter = contractBalMid - _am.

        assert(
            collectReverted
            ? (afterBalance == midBalance && contractBalAfter == contractBalMid && afterUnlock == midUnlock)
            : (midBalance >= _am && afterBalance + _am == midBalance && contractBalAfter + _am == contractBalMid)
        );
    }

    // Allow receiving Ether to fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We pass three parameters: putAmount to fund a Put, unlockOffset to set unlock time relative to now,
    // and collectAmount to attempt a Collect. The function is payable so the test harness can provide
    // Ether to forward for Put.
    function run(uint unlockOffset, uint putAmount, uint collectAmount) public payable {
        // ensure we can forward putAmount to c.Put
        require(address(this).balance >= putAmount);

        // Read holder state before any operations
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;
        uint minSum = c.MinSum();

        // Call Put to set up balance/unlockTime (may revert)
        uint unlockTime = block.timestamp + unlockOffset;
        bool putReverted;
        try c.Put{value: putAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe state after Put (these are the preconditions visible to Collect)
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint contractBalMid = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe state after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // Assert the general rule:
        // If Collect succeeded then the visible preconditions held (midBalance >= minSum, midBalance >= collectAmount,
        // and block.timestamp > midUnlock) and as a result the stored balance decreased by exactly collectAmount and
        // the contract balance decreased by exactly collectAmount. If Collect reverted then the stored balance and
        // contract balance remained unchanged by the Collect call (they equal the mid-values).
        assert(
            collectReverted
            ? (afterBalance == midBalance && contractBalAfter == contractBalMid && afterUnlock == midUnlock)
            : (
                midBalance >= minSum && midBalance >= collectAmount && block.timestamp > midUnlock
                && afterBalance + collectAmount == midBalance && contractBalAfter + collectAmount == contractBalMid
              )
        );
    }

    // allow receiving Ether to fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // putAmount: Ether to forward to Put to fund the holder (can be zero)
    // unlockOffset: seconds to add to block.timestamp when calling Put
    // collectAmount: requested amount to Collect
    function run(uint unlockOffset, uint putAmount, uint collectAmount) public payable {
        // allow forwarding putAmount
        require(address(this).balance >= putAmount);

        // Read holder state before any operations
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Call Put to possibly increase our stored balance and set unlockTime (may revert)
        uint unlockTime = block.timestamp + unlockOffset;
        bool putReverted;
        try c.Put{value: putAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe state after Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint contractBalMid = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe state after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule:
        // - If Collect succeeded: stored balance decreased exactly by collectAmount (afterBalance + collectAmount == midBalance)
        //   and contract balance decreased by at least collectAmount (contractBalMid >= contractBalAfter && contractBalMid - contractBalAfter >= collectAmount).
        // - If Collect reverted: neither the stored balance nor the contract balance increased as a result of Collect
        //   (afterBalance <= midBalance && contractBalAfter <= contractBalMid).
        assert(
            collectReverted
            ? (afterBalance <= midBalance && contractBalAfter <= contractBalMid)
            : (afterBalance + collectAmount == midBalance && contractBalMid >= contractBalAfter && (contractBalMid - contractBalAfter) >= collectAmount)
        );
    }

    // allow receiving Ether to fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // putAmount: Ether to forward to Put; unlockOffset: seconds to add to block.timestamp
    function run(uint unlockOffset, uint putAmount) public payable {
        // require we have the funds to forward
        require(address(this).balance >= putAmount);
        // keep parameters bounded to avoid weird overflow in the test environment
        require(unlockOffset <= 1 weeks);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        bool putReverted;
        // call Put with specified value
        try c.Put{value: putAmount}(block.timestamp + unlockOffset) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Put succeeded then stored balance increases exactly by putAmount and contract balance increases exactly by putAmount.
        // If Put reverted then neither stored balance nor contract balance changed.
        assert(
            putReverted
            ? (afterBalance == beforeBalance && contractBalAfter == contractBalBefore)
            : (afterBalance == beforeBalance + putAmount && contractBalAfter == contractBalBefore + putAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put to deposit some funds, then call Collect and assert that
    // when Collect does not revert, both address(c).balance and Acc[msg.sender].balance
    // reflect the withdrawal of exactly _am.
    function run(uint putUnlock, uint collectAmt, uint putAmt) public payable {
        require(address(this).balance >= putAmt, "insufficient balance to fund Put");
        // initial observed stored balance for this tester in contract c
        C.Holder memory beforeAcc = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Make a deposit via Put by sending Ether from this contract to c
        c.Put{value: putAmt}(putUnlock);

        // read after-deposit stored balance and contract balance
        C.Holder memory afterPutAcc = c.Acc(address(this));
        uint afterPutContractBal = address(c).balance;

        // Sanity: afterPutAcc.balance should be >= beforeAcc.balance (monotonic with deposit)
        // and contract balance should increase by putAmt. These are not the final assertion,
        // but help ensure the test proceeds meaningfully.
        // Now attempt to Collect collectAmt. It may revert; capture that.
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observed state after Collect attempt
        C.Holder memory afterCollectAcc = c.Acc(address(this));
        uint afterCollectContractBal = address(c).balance;

        // If Collect did not revert, then two things must hold:
        // 1) The contract's balance decreased by exactly collectAmt.
        // 2) The recorded Acc.balance for this address decreased by exactly collectAmt.
        // Formulate that as the single general assert below.
        assert(
            reverted || (
                afterPutContractBal == beforeContractBal + putAmt &&
                // contract balance decreased by collectAmt when Collect succeeded
                afterCollectContractBal + collectAmt == afterPutContractBal &&
                // recorded stored balance decreased by collectAmt when Collect succeeded
                afterCollectAcc.balance + collectAmt == afterPutAcc.balance
            )
        );
    }

    // Allow this test contract to receive Ether so it can fund Put operations.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Deposit some Ether with Put, then attempt Collect; assert that if Collect succeeds,
    // then address(c).balance and c.Acc(address(this)).balance each decrease exactly by _collectAmt.
    function run(uint putUnlock, uint _collectAmt, uint _putAmt) public payable {
        require(address(this).balance >= _putAmt, "insufficient balance to fund Put");

        // Read observable state before any calls
        uint beforeContractBal = address(c).balance;
        uint beforeStoredBal = c.Acc(address(this)).balance;

        // Make a deposit via Put by sending Ether from this contract to c
        c.Put{value: _putAmt}(putUnlock);

        // Read observable state after Put
        uint afterPutContractBal = address(c).balance;
        uint afterPutStoredBal = c.Acc(address(this)).balance;

        // Attempt Collect; capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(_collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after Collect attempt
        uint afterCollectContractBal = address(c).balance;
        uint afterCollectStoredBal = c.Acc(address(this)).balance;

        // General property:
        // - If Collect reverted then the contract's balance and stored balance must be unchanged from after Put.
        // - If Collect succeeded then both balances must have decreased by exactly _collectAmt.
        assert(
            reverted
            ? (afterCollectContractBal == afterPutContractBal && afterCollectStoredBal == afterPutStoredBal)
            : (afterPutContractBal == beforeContractBal + _putAmt && // sanity: deposit increased contract balance
               afterPutStoredBal == beforeStoredBal + _putAmt &&   // and stored balance
               afterCollectContractBal + _collectAmt == afterPutContractBal &&
               afterCollectStoredBal + _collectAmt == afterPutStoredBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Deposit some Ether with Put, then attempt Collect; assert the relationship between balances and revert.
    function run(uint putUnlock, uint _collectAmt, uint _putAmt) public payable {
        require(address(this).balance >= _putAmt, "insufficient balance to fund Put");

        // Observe before-values
        uint beforeContractBal = address(c).balance;
        // c.Acc returns (unlockTime, balance) as a struct via the public getter; read both and take the balance
        (, uint beforeStoredBal) = c.Acc(address(this));

        // Make a deposit via Put
        c.Put{value: _putAmt}(putUnlock);

        // Observe after Put
        uint afterPutContractBal = address(c).balance;
        (, uint afterPutStoredBal) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(_collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after Collect attempt
        uint afterCollectContractBal = address(c).balance;
        (, uint afterCollectStoredBal) = c.Acc(address(this));

        // General property:
        // If Collect reverted then balances unchanged from after Put.
        // If Collect succeeded then both the contract balance and stored balance decreased by exactly _collectAmt.
        assert(
            reverted
            ? (afterCollectContractBal == afterPutContractBal && afterCollectStoredBal == afterPutStoredBal)
            : (afterPutContractBal == beforeContractBal + _putAmt &&
               afterPutStoredBal == beforeStoredBal + _putAmt &&
               afterCollectContractBal + _collectAmt == afterPutContractBal &&
               afterCollectStoredBal + _collectAmt == afterPutStoredBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that Put{value: amt}(unlock) always increases address(c).balance and Acc(msg.sender).balance by exactly amt (and never decreases them).
    function run(uint unlock, uint amt) public payable {
        // ensure this test contract has the Ether to send
        require(address(this).balance >= amt, "insufficient balance");

        // observe before-values
        uint beforeContractBal = address(c).balance;
        (, uint beforeStoredBal) = c.Acc(address(this));

        // perform Put sending amt wei
        c.Put{value: amt}(unlock);

        // observe after-values
        uint afterContractBal = address(c).balance;
        (, uint afterStoredBal) = c.Acc(address(this));

        // General invariant: Put increases both balances by exactly amt (which may be zero), i.e.
        // afterContractBal == beforeContractBal + amt and afterStoredBal == beforeStoredBal + amt
        // This asserts neither balance ever decreases and the increase equals the value sent.
        assert(afterContractBal == beforeContractBal + amt && afterStoredBal == beforeStoredBal + amt);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to withdraw, and an arbitrary unlockTime for a prior Put, and deposit amount to set up balance
    function run(uint depositUnlock, uint depositAmt, uint collectAmt) public payable {
        // ensure this contract has Ether to deposit
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // Initial observation of this holder's stored values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform a Put to ensure the holder has at least depositAmt added to its recorded balance
        c.Put{value: depositAmt}(depositUnlock);

        // Observe after deposit and then attempt Collect; must capture whether Collect reverted
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        bool reverted;
        // Collect is payable in the contract signature; send zero value when trying to collect
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // If Collect succeeded (did not revert) then:
        // 1) midBal >= c.MinSum() and midBal >= collectAmt and block.timestamp > midUnlock must have held before the Collect call.
        // 2) afterBal == midBal - collectAmt (i.e., recorded balance decreased exactly by collectAmt).
        // 3) contract balance decreased by exactly collectAmt.
        // If Collect reverted then the stored balance and contract balance remain unchanged from the mid-state.

        // We can only observe c.MinSum via its public getter and Acc via getter; read MinSum now.
        uint minSum = c.MinSum();

        bool cond_required = (midBal >= minSum) && (midBal >= collectAmt) && (block.timestamp > midUnlock);
        bool balances_decreased_properly = (!reverted) ? (afterBal == midBal - collectAmt && afterContractBal + collectAmt == beforeContractBal + depositAmt) : (afterBal == midBal && afterContractBal == beforeContractBal + depositAmt);

        // The assert composes the implication: if Collect succeeded then cond_required and proper decreases held; if reverted then state unchanged.
        assert((!reverted && cond_required && balances_decreased_properly) || (reverted && balances_decreased_properly));
    }

    // receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We implement a test that calls Put with some unlockTime and value amount.
    // We assert that if the call does not revert, then the public Acc(this).balance
    // (queried via the autogenerated getter) is >= the previous balance and
    // the contract's ether balance increased by exactly the sent amount.

    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);
        // Read observable before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;

        // make the call and detect revert
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        // If the call succeeded, then the stored balance for this tester must be >= before
        // and the contract's ether balance must have increased by exactly amount.
        // If it reverted, no guarantees assumed. This is a general property of Put.
        assert(reverted || (afterBalance >= beforeBalance && cBalanceAfter == cBalanceBefore + amount));
    }

    // allow receiving Ether when contract sends back funds in Collect
    receive() external payable {}
}

