        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        assertTrue(reverted || (afterBalance >= beforeBalance && cBalanceAfter == cBalanceBefore + amount));
    }

    function testFuzz_run(uint256 unlockTime, uint256 amount) public {
        _run(unlockTime, amount);
    }

    receive() external payable {}
}

