        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If call did not revert, the public balance increased by exactly amount
        // and the contract's balance increased by at least amount.
        assert(reverted || (afterBal == beforeBal + amount && contractBalAfter >= contractBalBefore + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first fund the contract by calling Put with some initial deposit so that Collect may possibly succeed.
    // Inputs:
    //  - initialUnlock: unlockTime to set when depositing
    //  - initialAmount: ether sent to Put to create a positive balance
    //  - withdraw: amount attempted to Collect
    // We require this test contract to have enough balance to send initialAmount.
    function run(uint initialUnlock, uint initialAmount, uint withdraw) public payable {
        require(address(this).balance >= initialAmount);

        // Read before-values for this test contract's holder record and balances
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Make a top-level call to Put to deposit initialAmount into c under this contract's holder
        bool putReverted;
        try c.Put{value: initialAmount}(initialUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put, try to Collect withdraw amount. Capture whether Collect reverted.
        bool collectReverted;
        try c.Collect{value:0}(withdraw) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Collect succeeded (did not revert) then: the recorded balance decreased by exactly withdraw
        // and this test contract's balance (address(this).balance) increased by at least withdraw.
        // We cannot directly observe address(this).balance change relative to before inside c, but we can
        // reason using contract's balance: if Collect succeeded then address(c).balance decreased by at least withdraw.
        // Therefore assert: either Collect reverted, or (afterBal + withdraw == (putReverted ? beforeBal : beforeBal + initialAmount) && contractBalAfter + withdraw <= contractBalBefore + (putReverted ? 0 : initialAmount));
        // Simplify: compute expected balance before collect as balBeforeForCollect.

        uint balBeforeForCollect = putReverted ? beforeBal : beforeBal + initialAmount;

        // The general rule: if collect did not revert then recorded balance decreased exactly by withdraw
        // and contract's balance decreased by at least withdraw.
        assert(collectReverted || (afterBal + withdraw == balBeforeForCollect && contractBalBefore >= contractBalAfter + withdraw));
    }

    // Accept Ether so Put can send to this contract during tests if needed
    receive() external payable {}
}
